from admissions_records import *
def make(id,url,en,ru,e,a,change,docs=None):
 record(id,[route(english=e,academic=a,documents=docs,sources=[S(url,L(en,ru))])],change,['Fall 2027-specific applicability, exact IELTS variant/section minima where unstated and individual waiver eligibility need confirmation.'])

make('rhode-island-school-of-design','https://www.risd.edu/admissions/first-year/international-applicants','RISD international first-year requirements','RISD: требования иностранных первокурсников',
 {'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':7,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':93},{'period':'post2026','min':5}]},'alternatives':L('Duolingo 120. TOEFL MyBest/Home Edition and IELTS UKVI accepted; IELTS UKVI General is not accepted. These rules also apply to second-language-English US citizens.','Duolingo 120. TOEFL MyBest/Home Edition и IELTS UKVI принимаются; IELTS UKVI General — нет. Правила также относятся к гражданам США с английским как вторым языком.'),'waiver':L('SAT Reading/Writing 600 or ACT English AND Reading 25; or completed English-medium secondary schooling with three consecutive full-time years without ESL/ELL/ENL and an approved waiver form.','SAT Reading/Writing 600 либо ACT English И Reading 25; либо завершённая средняя школа на английском с тремя последовательными очными годами без ESL/ELL/ENL и одобренной формой освобождения.')},
 {'satPolicy':'optional','note':L('SAT/ACT are not required for admission; optional academic submission and English-proof substitution are distinct.','SAT/ACT не обязательны для поступления; добровольная академическая подача и замена языкового подтверждения — разные основания.')},
 'Recorded IELTS 7, current TOEFL scale and specific waivers independently of optional academic tests.')

make('milwaukee-school-of-engineering','https://www.msoe.edu/admissions-aid/international-admissions/future-international-students/undergraduate-students/requirements/','MSOE international undergraduate requirements','MSOE: требования международного бакалавриата',
 {'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6.5,'sections':dict.fromkeys(['reading','writing','listening','speaking'],6),'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':82,'sections':dict.fromkeys(['reading','writing','listening','speaking'],19)},{'period':'post2026','min':4.5,'sections':dict.fromkeys(['reading','writing','listening','speaking'],4)}]},'alternatives':L('Duolingo 115 with minimum band 100; PTE 56. These are full-admission requirements; a universal waiver was not established.','Duolingo 115 с минимумом секции 100; PTE 56. Это требования полного приёма; универсальное освобождение не установлено.')},
 {'satPolicy':'unknown','note':L('The international document checklist does not state a SAT/ACT rule. This omission is not treated as proof of optional admission.','Международный список документов не формулирует правило SAT/ACT. Отсутствие упоминания не считается доказательством необязательности.')},
 'Added actual IELTS/TOEFL section minima and language alternatives; preserved the unresolved academic-testing rule.',[L('All secondary/post-secondary transcripts, passport, financial certification and bank evidence for one year; international first-years normally live on campus for two years.','Все школьные/послешкольные оценки, паспорт, финансовое и банковское подтверждение одного года; иностранные первокурсники обычно живут в кампусе два года.')])

make('st-john-fisher-university','https://www.sjf.edu/student-life/international-student-services/admissions/first-year-admissions/','Fisher international first-year test alternatives','Fisher: альтернативы тестирования иностранных первокурсников',
 {'requirement':'alternatives-with-academic','ielts':{'accepted':True,'min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':None}],'note':L('The source prints an internet TOEFL minimum as 79–80, plus paper 550/computer 213; the ambiguous internet boundary is not collapsed into one confirmed number.','Источник печатает интернет-минимум TOEFL как 79–80, плюс бумажный 550/компьютерный 213; неоднозначная интернет-граница не превращается в одно подтверждённое число.')},'alternatives':L('The checklist requires at least one of SAT/ACT OR, for a non-native English speaker, TOEFL, Duolingo 105 or IELTS 6.5. It does not require SAT in addition to an accepted English alternative.','Список требует хотя бы один SAT/ACT ЛИБО, для неносителя английского, TOEFL, Duolingo 105 или IELTS 6,5. SAT сверх принимаемой языковой альтернативы не требуется.')},
 {'satPolicy':'conditional','note':L('SAT/ACT are one checklist alternative alongside specified English tests. Whether the applicant qualifies for the alternative must be checked; no independent compulsory SAT is inferred.','SAT/ACT — одна из альтернатив списка вместе с указанными языковыми тестами. Право кандидата на альтернативу нужно сверить; независимый обязательный SAT не предполагается.')},
 'Preserved the published OR between academic and English evidence instead of requiring both tests.',[L('All school records, NACES evaluation for school years outside the US, counselor/teacher recommendation and an essay of at least 250 words.','Все школьные документы, NACES для школьных лет вне США, рекомендация консультанта/учителя и эссе минимум 250 слов.')])

make('siena-university','https://www.siena.edu/offices/admissions/international-students/how-to-apply/','Siena international degree application requirements','Siena: требования международной заявки на степень',
 {'requirement':'required-by-language-country','ielts':{'accepted':True,'min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':79}]},'alternatives':L('Duolingo 115. The requirement refers to native language/language of instruction. Applicants below the stated levels may receive conditional admission via an approved partner; that is not unconditional direct entry.','Duolingo 115. Требование связано с родным языком/языком обучения. Ниже указанных уровней возможно условное поступление через одобренного партнёра; это не безусловный прямой приём.')},
 {'satPolicy':'optional'},'Recorded direct-entry language minima and distinguished an approved conditional partner pathway from direct admission.')

make('hampton-university','https://home.hamptonu.edu/admissions/international-students/','Hampton international first-year document requirements','Hampton: документы иностранных первокурсников',
 {'requirement':'required-unless-exempt','ielts':{'accepted':None,'min':None},'toefl':{'accepted':True,'min':None},'alternatives':L('The international page lists TOEFL, SAT/ACT or Duolingo for non-native English applicants, without score thresholds. IELTS acceptance and a numerical threshold were not established.','Международная страница перечисляет TOEFL, SAT/ACT либо Duolingo для неносителей английского без балльных порогов. Приём IELTS и числовой порог не установлены.')},
 {'satPolicy':'required','note':L('The international application checklist explicitly requests official SAT or ACT. The page has no intake year, so this is reference evidence until Fall 2027 is confirmed.','Международный список заявки прямо требует официальный SAT либо ACT. Год набора не указан, поэтому до подтверждения Fall 2027 это справочное основание.')},
 'Exposed the stated international SAT/ACT obligation without inventing IELTS acceptance or language scores.',[L('Official school diploma/transcripts and English translations; credential evaluation may be requested. West African applicants have specific WASSCE/GCE evidence rules.','Официальные школьный диплом/оценки и английские переводы; могут запросить оценку квалификации. Для западноафриканских кандидатов отдельные правила WASSCE/GCE.')])
finish()
